import{_ as s,o as t,c as n,a3 as m}from"./chunks/framework.B9qR_F1m.js";const g=JSON.parse('{"title":"市场结构","description":"按厂商数量、产品差异与进入壁垒三个维度划分四种市场结构，逐一推导其均衡条件、长期利润与社会福利后果。","frontmatter":{"title":"市场结构","date":"2026-10-19T00:00:00.000Z","subject":"economics","subjectLabel":"经济学","category":"微观经济学","tags":["市场结构","完全竞争","垄断"],"description":"按厂商数量、产品差异与进入壁垒三个维度划分四种市场结构，逐一推导其均衡条件、长期利润与社会福利后果。"},"headers":[],"relativePath":"subjects/economics/micro/market-structure.md","filePath":"subjects/economics/micro/market-structure.md","lastUpdated":null}'),e={name:"subjects/economics/micro/market-structure.md"};function l(p,a,i,r,h,c){return t(),n("div",null,[...a[0]||(a[0]=[m('<h1 id="市场结构" tabindex="-1">市场结构 <a class="header-anchor" href="#市场结构" aria-label="Permalink to &quot;市场结构&quot;">​</a></h1><blockquote><p><strong>一句话概括</strong>：市场结构决定了厂商有没有定价权——竞争越充分，价格越接近成本。</p></blockquote><h2 id="一、划分维度" tabindex="-1">一、划分维度 <a class="header-anchor" href="#一、划分维度" aria-label="Permalink to &quot;一、划分维度&quot;">​</a></h2><p>市场结构主要由三个因素决定：</p><ol><li><strong>厂商数量</strong>：买者与卖者的多少；</li><li><strong>产品差异</strong>：产品是完全同质，还是存在差异；</li><li><strong>进入壁垒</strong>：新厂商进入市场的难易程度。</li></ol><h2 id="二、四种市场结构对比" tabindex="-1">二、四种市场结构对比 <a class="header-anchor" href="#二、四种市场结构对比" aria-label="Permalink to &quot;二、四种市场结构对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结构</th><th>厂商数量</th><th>产品</th><th>进入壁垒</th><th>定价权</th><th>需求曲线</th></tr></thead><tbody><tr><td>完全竞争</td><td>极多</td><td>完全同质</td><td>无</td><td>无（价格接受者）</td><td>水平线</td></tr><tr><td>垄断竞争</td><td>较多</td><td>有差异</td><td>低</td><td>有限</td><td>向右下倾斜，较平缓</td></tr><tr><td>寡头</td><td>少数几家</td><td>同质或有差异</td><td>高</td><td>较强，且相互依存</td><td>折弯的需求曲线</td></tr><tr><td>完全垄断</td><td>唯一</td><td>无相近替代品</td><td>极高</td><td>强</td><td>向右下倾斜（市场需求曲线）</td></tr></tbody></table><h2 id="三、完全竞争" tabindex="-1">三、完全竞争 <a class="header-anchor" href="#三、完全竞争" aria-label="Permalink to &quot;三、完全竞争&quot;">​</a></h2><h3 id="均衡条件" tabindex="-1">均衡条件 <a class="header-anchor" href="#均衡条件" aria-label="Permalink to &quot;均衡条件&quot;">​</a></h3><p>厂商利润最大化的一阶条件始终是 <strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mi>R</mi><mo>=</mo><mi>M</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">MR = MC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span></strong>。在完全竞争下，单个厂商面对水平需求曲线， 因此 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>=</mo><mi>M</mi><mi>R</mi><mo>=</mo><mi>A</mi><mi>R</mi></mrow><annotation encoding="application/x-tex">P = MR = AR</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>，均衡条件简化为：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>P</mi><mo>=</mo><mi>M</mi><mi>R</mi><mo>=</mo><mi>M</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">P = MR = MC </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span></span></p><h3 id="短期与长期" tabindex="-1">短期与长期 <a class="header-anchor" href="#短期与长期" aria-label="Permalink to &quot;短期与长期&quot;">​</a></h3><ul><li><strong>短期</strong>：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>&gt;</mo><mi>A</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">P &gt; AC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 时获正利润，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>V</mi><mi>C</mi><mo>&lt;</mo><mi>P</mi><mo>&lt;</mo><mi>A</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">AVC &lt; P &lt; AC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 时亏损但继续生产，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>&lt;</mo><mi>A</mi><mi>V</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">P &lt; AVC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 时停业；</li><li><strong>长期</strong>：正利润吸引新厂商进入，供给增加使价格下降，直到 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>=</mo><mi>min</mi><mo>⁡</mo><mo stretchy="false">(</mo><mi>A</mi><mi>C</mi><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">P = \\min(AC)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">min</span><span class="mopen">(</span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mclose">)</span></span></span></span>， 此时经济利润为零，厂商只获得正常利润。</li></ul><blockquote><p><strong>注意</strong>：经济利润为零不等于不赚钱，它表示资源获得的回报恰好等于其机会成本。</p></blockquote><h3 id="效率评价" tabindex="-1">效率评价 <a class="header-anchor" href="#效率评价" aria-label="Permalink to &quot;效率评价&quot;">​</a></h3><p>长期均衡下 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>=</mo><mi>M</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">P = MC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>，资源配置达到帕累托最优，且生产位于平均成本最低点， 同时实现<strong>配置效率</strong>与<strong>生产效率</strong>。</p><h2 id="四、完全垄断" tabindex="-1">四、完全垄断 <a class="header-anchor" href="#四、完全垄断" aria-label="Permalink to &quot;四、完全垄断&quot;">​</a></h2><h3 id="均衡与定价" tabindex="-1">均衡与定价 <a class="header-anchor" href="#均衡与定价" aria-label="Permalink to &quot;均衡与定价&quot;">​</a></h3><p>垄断者仍遵循 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mi>R</mi><mo>=</mo><mi>M</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">MR = MC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>，但因需求曲线向下倾斜，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mi>R</mi><mo>&lt;</mo><mi>P</mi></mrow><annotation encoding="application/x-tex">MR &lt; P</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span>，故 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>&gt;</mo><mi>M</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">P &gt; MC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>。 加成定价幅度由需求弹性决定（勒纳指数）：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>L</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mo>−</mo><mi>M</mi><mi>C</mi></mrow><mi>P</mi></mfrac><mo>=</mo><mfrac><mn>1</mn><mrow><mi mathvariant="normal">∣</mi><msub><mi>E</mi><mi>d</mi></msub><mi mathvariant="normal">∣</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">L = \\frac{P - MC}{P} = \\frac{1}{|E_d|} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:2.2574em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>需求越缺乏弹性，垄断者的加成越高。</p><h3 id="价格歧视" tabindex="-1">价格歧视 <a class="header-anchor" href="#价格歧视" aria-label="Permalink to &quot;价格歧视&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级</th><th>做法</th><th>结果</th><th>例子</th></tr></thead><tbody><tr><td>一级</td><td>按每个人的支付意愿逐一收费</td><td>榨取全部消费者剩余</td><td>个性化议价</td></tr><tr><td>二级</td><td>按购买量分段定价</td><td>部分获取消费者剩余</td><td>阶梯电价、批量折扣</td></tr><tr><td>三级</td><td>按可识别的群体划分市场，分别定价</td><td>弹性小的市场定高价</td><td>学生票、景区票价</td></tr></tbody></table><p>三级歧视的定价规则：各市场满足 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><msub><mi>R</mi><mn>1</mn></msub><mo>=</mo><mi>M</mi><msub><mi>R</mi><mn>2</mn></msub><mo>=</mo><mi>M</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">MR_1 = MR_2 = MC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>，弹性较小的市场收取更高价格。</p><h3 id="福利后果" tabindex="-1">福利后果 <a class="header-anchor" href="#福利后果" aria-label="Permalink to &quot;福利后果&quot;">​</a></h3><p>垄断导致产量低于社会最优水平，产生<strong>无谓损失</strong>（deadweight loss）， 数量为垄断价格与竞争价格之间、需求曲线与边际成本曲线围成的三角形面积。</p><h2 id="五、垄断竞争" tabindex="-1">五、垄断竞争 <a class="header-anchor" href="#五、垄断竞争" aria-label="Permalink to &quot;五、垄断竞争&quot;">​</a></h2><p>特征：厂商多、产品有差异、自由进入。</p><ul><li><strong>短期</strong>：因产品有差异，需求曲线向下倾斜，可能出现正利润；</li><li><strong>长期</strong>：自由进入使利润趋于零，均衡时 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>=</mo><mi>A</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">P = AC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 且 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi><mi>R</mi><mo>=</mo><mi>M</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">MR = MC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>， 此时 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo>&gt;</mo><mi>M</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">P &gt; MC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span>，产量低于平均成本最低点，存在<strong>过剩生产能力</strong>。</li></ul><p>权衡：产品多样性带来的选择价值，与小规模生产带来的效率损失之间的取舍。</p><h2 id="六、寡头" tabindex="-1">六、寡头 <a class="header-anchor" href="#六、寡头" aria-label="Permalink to &quot;六、寡头&quot;">​</a></h2><p>核心特征是<strong>策略相互依存</strong>：每家厂商的利润都取决于对手的行为，因此必须用博弈论分析。</p><table tabindex="0"><thead><tr><th>模型</th><th>假设</th><th>均衡结果</th></tr></thead><tbody><tr><td>古诺模型</td><td>同时选择产量，假设对手产量不变</td><td>产量介于竞争与垄断之间</td></tr><tr><td>伯特兰模型</td><td>同时选择价格，产品同质</td><td>价格降至边际成本（伯特兰悖论）</td></tr><tr><td>斯塔克尔伯格模型</td><td>领导者先定产量，跟随者后定</td><td>领导者获得先动优势</td></tr><tr><td>折弯需求曲线</td><td>对手跟跌不跟涨</td><td>价格黏性</td></tr></tbody></table><p><strong>囚徒困境</strong>解释了为什么卡特尔天然不稳定：每家厂商都有&quot;暗中降价扩大销量&quot;的占优策略， 合谋产量难以维持。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确说法</th></tr></thead><tbody><tr><td>垄断企业可以任意定价</td><td>受需求曲线约束，定价过高会导致销量骤减</td></tr><tr><td>竞争市场长期利润为零，所以没人愿意做</td><td>会计利润仍为正，只是经济利润为零</td></tr><tr><td>垄断一定违法</td><td>自然垄断、专利保护下的垄断是法律允许的</td></tr></tbody></table><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>平狄克《微观经济学》第 10—12 章</li><li>曼昆《经济学原理》（微观分册）第 15—17 章</li></ul>',38)])])}const d=s(e,[["render",l]]);export{g as __pageData,d as default};
